#include <Arduino.h>
#include <string.h>

const byte LED_PIN = 9;
char command[24];
byte used = 0;
bool overflowed = false;
unsigned long lastByte = 0;
unsigned long lastFade = 0;
byte mode = 0;
int brightness = 0;
int direction = 1;

void finishCommand() {
  command[used] = '\0';
  if (!overflowed) {
    if (strcmp(command, "MODE1") == 0) {
      mode = 1;
      brightness = 0;
      direction = 1;
      lastFade = millis();
      analogWrite(LED_PIN, brightness);
    } else if (strcmp(command, "MODE2") == 0) {
      mode = 2;
      analogWrite(LED_PIN, 255);
    }
  }
  used = 0;
  overflowed = false;
}

void setup() {
  pinMode(LED_PIN, OUTPUT);
  analogWrite(LED_PIN, 0);
  Serial.begin(9600);
}

void loop() {
  while (Serial.available() > 0) {
    char c = (char)Serial.read();
    lastByte = millis();
    if (c == '\n' || c == '\r') {
      finishCommand();
    } else if (used < sizeof(command) - 1) {
      command[used++] = c;
    } else {
      overflowed = true;
    }
  }
  unsigned long now = millis();
  if ((used || overflowed) && now - lastByte >= 20) {
    finishCommand();
  }
  if (mode == 1 && now - lastFade >= 10) {
    lastFade = now;
    brightness += direction;
    if (brightness >= 255) {
      brightness = 255;
      direction = -1;
    } else if (brightness <= 0) {
      brightness = 0;
      direction = 1;
    }
    analogWrite(LED_PIN, brightness);
  }
}
